/* Platform selector for the pinned libarchive 3.8.1 config sets generated by
 * the verified CMake builds (see RECIPE.md). SwiftPM passes only
 * -DHAVE_CONFIG_H; the compiler-provided __APPLE__/__ANDROID__ macros choose
 * the frozen config. Do not edit the two platform files: regenerate them
 * with the documented cmake invocation and diff before committing.
 */
#if defined(HAVE_CONFIG_H) && !defined(FLOE_LIBARCHIVE_CONFIG_WRAPPER_H)
#define FLOE_LIBARCHIVE_CONFIG_WRAPPER_H
#if defined(__APPLE__)
#include "config-macos.h"
#elif defined(__ANDROID__)
#include "config-android.h"
#else
#error "libarchive 3.8.9 vendored build is pinned for Apple host tests and Android arm64 only"
#endif
#endif
